#!/usr/bin/env node
/**
 * Builds the offline reader pages that run inside the WebView:
 *   web-reader/*.js + vendor libraries  →  src/reader/web/*.generated.ts
 *
 * The generated files are committed, so you only need this after editing
 * web-reader/. Vendor libraries are not app dependencies; install them into
 * a throwaway folder and point the script at it:
 *
 *   mkdir ../reader-vendor && cd ../reader-vendor && npm init -y
 *   npm i epubjs@0.3.93 jszip@3.10.1 pdfjs-dist@3.11.174 --ignore-scripts
 *   cd ../steadyview && node scripts/build-reader-html.mjs ../reader-vendor/node_modules
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const vendor = resolve(process.argv[2] ?? join(root, '..', 'reader-vendor', 'node_modules'));
const read = (p) => readFileSync(p, 'utf8');

function inline(js, label) {
  if (/<\/script/i.test(js)) throw new Error(`${label} contains </script and cannot be inlined`);
  return js;
}

/*
 * Books must never reach the network: a remote image in an EPUB would work as a
 * tracking pixel. Only the page's own inline code and the book's embedded
 * resources (blob:/data: URLs created by epub.js / pdf.js) may load.
 */
const CSP = [
  "default-src 'none'",
  "script-src 'unsafe-inline'",
  "style-src 'unsafe-inline' blob: data:",
  "img-src blob: data:",
  "font-src blob: data:",
  "media-src blob: data:",
  "connect-src blob: data:",
  "frame-src blob: data: about:",
  "form-action 'none'",
].join('; ');
const CSP_META = `<meta http-equiv="Content-Security-Policy" content="${CSP}">`;

const VIEWPORT_FIXED = 'width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover';
const VIEWPORT_ZOOM = 'width=device-width, initial-scale=1, maximum-scale=4, viewport-fit=cover';

const epubHtml = `<!doctype html><html><head><meta charset="utf-8">
${CSP_META}
<meta name="viewport" content="${VIEWPORT_FIXED}">
<style>
html,body{margin:0;padding:0;height:100%;overflow:hidden;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none;-webkit-tap-highlight-color:transparent;touch-action:none;}
#viewer{position:absolute;top:0;bottom:0;left:0;right:0;}
</style>
<script>${inline(read(join(vendor, 'jszip/dist/jszip.min.js')), 'jszip')}</script>
<script>${inline(read(join(vendor, 'epubjs/dist/epub.min.js')), 'epubjs')}</script>
</head><body><div id="viewer"></div>
<script>${inline(read(join(root, 'web-reader/epub-app.js')), 'epub-app')}</script>
</body></html>`;

const pdfHtml = `<!doctype html><html><head><meta charset="utf-8">
${CSP_META}
<meta name="viewport" content="${VIEWPORT_ZOOM}">
<style>
html,body{margin:0;padding:0;-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent;}
#pages{min-height:100vh;box-sizing:border-box;}
.page{position:relative;border-radius:2px;box-shadow:0 1px 3px rgba(0,0,0,.18);overflow:hidden;}
.page canvas{display:block;width:100%;height:100%;}
</style>
<style id="sv-style"></style>
<script>${inline(read(join(vendor, 'pdfjs-dist/build/pdf.min.js')), 'pdfjs')}</script>
<script>${inline(read(join(vendor, 'pdfjs-dist/build/pdf.worker.min.js')), 'pdf worker')}</script>
</head><body><div id="pages"></div>
<script>${inline(read(join(root, 'web-reader/pdf-app.js')), 'pdf-app')}</script>
</body></html>`;

const outDir = join(root, 'src/reader/web');
mkdirSync(outDir, { recursive: true });
const banner = '/* eslint-disable */\n// GENERATED by scripts/build-reader-html.mjs — do not edit. Edit web-reader/ instead.\n';
writeFileSync(join(outDir, 'epubHtml.generated.ts'), `${banner}export const EPUB_HTML = ${JSON.stringify(epubHtml)};\n`);
writeFileSync(join(outDir, 'pdfHtml.generated.ts'), `${banner}export const PDF_HTML = ${JSON.stringify(pdfHtml)};\n`);
console.log(`Wrote reader pages (epub ${(epubHtml.length / 1024) | 0} KB, pdf ${(pdfHtml.length / 1024) | 0} KB)`);
